mapper.select:
SELECT t.id, t.nursing_id, t.project_id, t.project_name, t.elder_id, t.elder_name, t.bed_number, t.estimated_server_time, t.real_server_time, t.mark, t.cancel_reason, t.status, t.task_image, t.create_time, t.update_time, t.remark, su.nick_name AS nursing_name FROM nursing_task t LEFT JOIN sys_user su ON FIND_IN_SET(su.user_id, t.nursing_id)
AND t.elder_name LIKE CONCAT('%', #{elderName}, '%')
AND FIND_IN_SET(#{nurseId}, t.nursing_id)
AND t.project_id = #{projectId}
AND t.status = #{status}
AND t.estimated_server_time >= #{startTime}
AND t.estimated_server_time <= #{endTime}
ORDER BY t.estimated_server_time DESC
